        sendHtml(200, projectList('', '', url.searchParams.get('filter') === 'Archived' ? 'Archived' : 'Active'));
      } else if (request.method === 'POST' && pathname === '/projects') {
        const body = await readForm(request);
        const name = (body.get('name') ?? '').trim();
